sample.code:
#include <iostream>
using namespace std;

int main() {
    int a[6] = {34, 12, 78, 5, 66, 41};
    int maxVal = a[0];
    int maxPos = 0;
    for (int i = 1; i < 6; i++) {
        if (a[i] > maxVal) {
            maxVal = a[i];
            maxPos = i;
        }
    }
    cout << "Max = " << maxVal << " at index " << maxPos << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    int a[20];
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    int maxVal = a[0];
    int minVal = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] > maxVal) {
            maxVal = a[i];
        }
        if (a[i] < minVal) {
            minVal = a[i];
        }
    }
    cout << "Max = " << maxVal << endl;
    cout << "Min = " << minVal << endl;
    cout << "Range = " << maxVal - minVal << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[6] = {45, 90, 72, 38, 15, 63};
    int maxPos = 0;
    for (int i = 1; i < 6; i++) {
        if (a[i] > a[maxPos]) {
            maxPos = i;
        }
    }
    int secondPos = -1;
    for (int i = 0; i < 6; i++) {
        if (i != maxPos && (secondPos == -1 || a[i] > a[secondPos])) {
            secondPos = i;
        }
    }
    cout << "Largest = " << a[maxPos] << " at index " << maxPos << endl;
    cout << "Second largest = " << a[secondPos] << " at index " << secondPos << endl;
    return 0;
}

